export interface AttemptPolicy {
  maxAttempts: number;
  backoffMs: number;
  maxBackoffMs: number;
}

// A job has just failed its `attempt`-th run (1-based). Returns when it should run
// again, or null once all `maxAttempts` runs have been used. Retry number n waits
// backoffDelay(n) with the policy's base delay and cap (no jitter).
export function nextAttemptAt(failedAt: Date, attempt: number, policy: AttemptPolicy): Date | null {
  if (attempt > policy.maxAttempts) return null;
  const delay = backoffDelay(attempt, { baseMs: policy.backoffMs, maxMs: policy.maxBackoffMs, jitter: 0 });
  return new Date(failedAt.getTime() + delay);
}

