// A worker picked the job up: one more attempt is used.
export function startJob(ctx: JobsContext, id: string): ApiResponse {
  const job = requireJob(ctx, id);
  if (!canTransition(job.status, "running")) {
    throw conflict(`job ${id} is ${job.status} and cannot become running`);
  }
  const now = ctx.clock();
  if (job.retryAt !== undefined && Date.parse(job.retryAt) > now.getTime()) {
    throw conflict(`job ${id} is backing off until ${job.retryAt}`);
  }
  const updated = ctx.store.setStatus(id, "running", { attempts: job.attempts + 1, retryAt: undefined });
  ctx.events.emit("job:started", updated);
  return json(200, toJobDto(updated, now));
}

// The run in progress failed: requeue with backoff while attempts remain.
export function failJob(ctx: JobsContext, id: string, request: ApiRequest): ApiResponse {
  const job = requireJob(ctx, id);
  if (job.status !== "running") throw conflict(`job ${id} is ${job.status}, not running`);
  const body = (request.body ?? {}) as { error?: unknown };
  const error = typeof body.error === "string" && body.error.trim() ? body.error.trim() : "job failed";
  const now = ctx.clock();
  const retryAt = nextAttemptAt(now, job.attempts + 1, job.retry);
  const updated = retryAt
    ? ctx.store.setStatus(id, "queued", { lastError: error, retryAt: retryAt.toISOString() })
    : ctx.store.setStatus(id, "failed", { lastError: error, retryAt: undefined });
  ctx.events.emit(retryAt ? "job:retry-scheduled" : "job:failed", updated);
  return json(200, toJobDto(updated, now));
}

export function succeedJob(ctx: JobsContext, id: string): ApiResponse {
  return transition(ctx, id, "succeeded", "job:succeeded", { lastError: undefined });
}
